prompt.text:
Repair the complete CommonJS module below and return a corrected complete source file.

The module must export exactly `{ chunkBytes, joinBytes }`.

`chunkBytes(bytes, maximum)` requires a `Uint8Array` and a positive integer maximum. It returns newly allocated `Uint8Array` chunks, in order, each no longer than maximum. Empty input returns `[]`. Every input byte must appear exactly once, including the final byte. Inputs must not be mutated or aliased.

`joinBytes(chunks)` requires an array of `Uint8Array` values, concatenates them in order, and returns a newly allocated `Uint8Array`. Empty chunks and an empty array are valid. Reject malformed arguments with `TypeError`.

Known-bad source:

"use strict";

function chunkBytes(bytes, maximum) {
  if (!(bytes instanceof Uint8Array) || !Number.isInteger(maximum) || maximum < 1) {
    throw new TypeError("invalid chunk arguments");
  }
  const chunks = [];
  for (let offset = 0; offset < bytes.length - 1; offset += maximum) {
    chunks.push(bytes.slice(offset, Math.min(offset + maximum, bytes.length)));
  }
  return chunks;
}

function joinBytes(chunks) {
  if (!Array.isArray(chunks) || chunks.some((chunk) => !(chunk instanceof Uint8Array))) {
    throw new TypeError("chunks must be byte arrays");
  }
  const length = chunks.reduce((sum, chunk) => sum + chunk.length, 0);
  const result = new Uint8Array(length);
  let offset = 0;
  for (const chunk of chunks) {
    result.set(chunk, offset);
    offset += chunk.length;
  }
  return result;
}

module.exports = { chunkBytes, joinBytes };

