"use strict";

const assert = require("node:assert/strict");
const api = require("./solution");
assert.deepStrictEqual(Object.keys(api).sort(), ["chunkBytes", "joinBytes"]);
const { chunkBytes, joinBytes } = api;

const input = new Uint8Array([0, 1, 2, 3, 254, 255]);
const original = new Uint8Array(input);
const chunks = chunkBytes(input, 2);
assert.strictEqual(chunks.length, 3);
assert.deepStrictEqual(chunks.map(Array.from), [[0, 1], [2, 3], [254, 255]]);
assert.deepStrictEqual(input, original);
for (const chunk of chunks) {
  assert.ok(chunk instanceof Uint8Array);
  assert.notStrictEqual(chunk.buffer, input.buffer);
}
chunks[0][0] = 99;
assert.strictEqual(input[0], 0);

const single = chunkBytes(new Uint8Array([42]), 10);
assert.deepStrictEqual(single.map(Array.from), [[42]]);
assert.deepStrictEqual(chunkBytes(new Uint8Array(0), 1), []);
assert.deepStrictEqual(chunkBytes(new Uint8Array([1, 2, 3]), 1).map(Array.from), [[1], [2], [3]]);

for (const args of [
  [[], 1],
  [new Uint8Array([1]), 0],
  [new Uint8Array([1]), -1],
  [new Uint8Array([1]), 1.5],
  [new Uint8Array([1]), NaN],
  [new Uint8Array([1]), Infinity]
]) {
  assert.throws(() => chunkBytes(args[0], args[1]), TypeError);
}

const left = new Uint8Array([1, 2]);
const empty = new Uint8Array(0);
const right = new Uint8Array([3, 4, 5]);
const joined = joinBytes([left, empty, right]);
assert.ok(joined instanceof Uint8Array);
assert.deepStrictEqual(Array.from(joined), [1, 2, 3, 4, 5]);
assert.notStrictEqual(joined.buffer, left.buffer);
assert.notStrictEqual(joined.buffer, right.buffer);
joined[0] = 9;
assert.deepStrictEqual(Array.from(left), [1, 2]);
left[1] = 8;
assert.strictEqual(joined[1], 2);

const emptyJoined = joinBytes([]);
assert.ok(emptyJoined instanceof Uint8Array);
assert.strictEqual(emptyJoined.length, 0);
const oneJoined = joinBytes([right]);
assert.deepStrictEqual(oneJoined, right);
assert.notStrictEqual(oneJoined.buffer, right.buffer);

for (const invalid of [null, {}, new Uint8Array(), [null], [[1, 2]], [new Uint8Array(), "bad"]]) {
  assert.throws(() => joinBytes(invalid), TypeError);
}

